import{_ as i,l as s,o as e,c as l,v as t,p as n,x as r,d as p,i as P,S as d}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"PAUSE 与 PFC","description":"","frontmatter":{"title":"PAUSE 与 PFC","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pause-pfc.md","filePath":"cs/pause-pfc.md","lastUpdated":1789023840000}'),E={name:"cs/pause-pfc.md"};function c(h,a,A,C,u,_){const o=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="pause-与-pfc" tabindex="-1">PAUSE 与 PFC <a class="header-anchor" href="#pause-与-pfc" aria-label="Permalink to &quot;PAUSE 与 PFC&quot;">​</a></h1><div class="epigraph"><p>链路层暂停是跳上的反压，不是端到端窗口；PFC 按优先级暂停，避免一张暂停卡死全部类别。</p><footer>—— 据 IEEE 802.3x PAUSE；IEEE 802.1Qbb PFC 整理</footer></div><p><a href="/cs/autonegotiation">上一课</a>可广告流控能力。缺口是<strong>暂停帧做什么</strong>：<a href="/cs/tcp-window">TCP 窗口</a> 保护接收主机；交换机输出队列满时，需要一跳内让对端停发。<a href="/cs/layering-e2e">端到端论证</a> 提醒：这是性能优化，不是文件正确性。本课不把巨帧 MTU 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>802.3x PAUSE：对端停止该口全部发送一段时间。无损存储网（后课 RoCE）怕丢包，于是用 PFC：八个优先级各有暂停，背压只打中无丢类别。HOL 后课会说明为何整口暂停会让无关流饿死——PFC 是针对类别的补丁，不是交换机结构的最终解。</p><p>PAUSE 跨越中间交换机时会传播拥塞，形成「停车波」。这不是 AIMD，没有公平定理。</p><p><span class="marginnote">PFC 依赖 802.1p 优先级字段。配错类别会让控制面 BPDU 也被暂停。本课不把 DCQCN 算法写完。</span></p><h3 id="暂停不是-rwnd" tabindex="-1">暂停不是 rwnd <a class="header-anchor" href="#暂停不是-rwnd" aria-label="Permalink to &quot;暂停不是 rwnd&quot;">​</a></h3><p>一跳反压保护邻机队列，不保护文件正确性。整口 PAUSE 会冻无关流；PFC 按类补，仍可能传播停车波。公网核心不要开。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>接收方队列过阈 → 发 PAUSE/PFC → 发送方停止对应队列 → 阈下恢复。画与 TCP 对照：rwnd 在两端主机；PAUSE 在相邻 MAC。不要用 PAUSE 替代拥塞控制来跑广域 TCP。</p>',11)),(e(),n(d,null,{default:r(()=>[P(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E5%87%BA%E5%8F%A3%E9%98%9F%E5%88%97%E8%BF%87%E9%98%88%22%5D%20--%3E%20PF%5B%22PAUSE%20%E6%88%96%20PFC%22%5D%0A%20%20PF%20--%3E%20NB%5B%22%E9%82%BB%E6%9C%BA%E5%81%9C%E5%8F%91%22%5D%0A%20%20NB%20--%3E%20DRAIN%5B%22%E9%98%9F%E5%88%97%E6%8E%92%E6%B3%84%22%5D%0A%20%20DRAIN%20--%3E%20RSM%5B%22%E6%81%A2%E5%A4%8D%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>主干交换课把全双工链路当成总能塞帧。本课承认缓冲有限。生成树阻塞口不发数据，与暂停不同：阻塞是拓扑，暂停是瞬态反压。LACP 后课的成员口各自暂停，逻辑链路仍在。</p><p>无损以太网 = 不丢 + 必须有足够缓冲与PFC 调参；丢仍可能发生在阈值配错时。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入量化拥塞通知的全部反馈环。巨帧与 MTU 是下一课。后课默认：PAUSE 整口、PFC 按类；都是一跳反压。</p><p>不要在互联网核心开 PFC：没有统一优先级语义，暂停会放大故障。</p><p>上一课留下的缺口在本课收口；「PAUSE 与 PFC」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/jumbo-mtu">巨帧与 MTU</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PAUSE/PFC 是链路反压，不是 rwnd。</li><li>PFC 按优先级隔离暂停，仍可能传播拥塞。</li><li>端到端正确性仍在 TCP/应用。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：IEEE 802.3x；IEEE 802.1Qbb。</li></ul>',10))])}const S=i(E,[["render",c]]);export{m as __pageData,S as default};
